/**
 * 文档设置初始化脚本
 * 在 DOM 完全加载后执行，设置开关事件监听器
 */
(function() {
    'use strict';
    
    // 等待 DOM 完全加载
    function initDocSettings() {
        // 延迟确保 DOM 元素存在
        setTimeout(function() {
            var docShowInfo = document.getElementById('docShowInfo');
            var docShowTime = document.getElementById('docShowTime');
            var docShowFooter = document.getElementById('docShowFooter');
            var saveDocConfig = document.getElementById('saveDocConfig');
            
            // 检查元素是否存在
            if (!docShowInfo || !docShowTime || !docShowFooter) {
                console.error('文档设置元素未找到');
                return;
            }
            
            // 开关切换 - 显示文档信息
            docShowInfo.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                this.classList.toggle('active');
                saveDocConfigState();
            });
            
            // 开关切换 - 显示时间戳
            docShowTime.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                this.classList.toggle('active');
                saveDocConfigState();
            });
            
            // 开关切换 - 显示尾部信息
            docShowFooter.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                this.classList.toggle('active');
                saveDocConfigState();
            });
            
            // 保存配置状态
            function saveDocConfigState() {
                var title = document.getElementById('docTitle');
                var footerText = document.getElementById('docFooterText');
                
                var config = {
                    title: title ? (title.value.trim() || '操作步骤') : '操作步骤',
                    showInfo: docShowInfo.classList.contains('active'),
                    showTime: docShowTime.classList.contains('active'),
                    showFooter: docShowFooter.classList.contains('active'),
                    footerText: footerText ? (footerText.value.trim() || '本文档由 AI 自动生成') : '本文档由 AI 自动生成'
                };
                
                chrome.storage.sync.set({ docConfig: config });
                
                // 显示保存提示
                var status = document.getElementById('docStatus');
                if (status) {
                    status.textContent = '文档设置已保存';
                    status.className = 'status-message status-success';
                    status.style.display = 'block';
                    setTimeout(function() {
                        status.style.display = 'none';
                    }, 2000);
                }
            }
            
            console.log('文档设置初始化完成');
        }, 300);
    }
    
    // 兼容 DOMContentLoaded 事件
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initDocSettings);
    } else {
        // DOM 已经加载完成
        initDocSettings();
    }
})();
